    if (lowercase) w = w.toLowerCase
    if (w.length < minLength) return None
    val adjusted = maxLength.map(m => if (w.length > m) w.take(m) else w).getOrElse(w)
    if (adjusted.nonEmpty) Some(adjusted) else None
  }

  def tokenize(text: String): List[Token] = {
    val words = text.split("\\s+").filter(_.nonEmpty)
    val tokens = ListBuffer.empty[Token]

    for ((word, idx) <- words.zipWithIndex) {
      processToken(word).foreach { processed =>
        tokens += Token(processed, TokenType.STRING, Map("position" -> idx, "original" -> word))
      }
    }

    tokens.toList
  }

  def tokenizeToStrings(text: String): List[String] = tokenize(text).map(_.value)

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val words = text.split("\\s+").filter(_.nonEmpty)
    val results = ListBuffer.empty[(String, Int, Int)]
    var currentPos = 0

    for (word <- words) {
      val start = text.indexOf(word, currentPos)
      val end = start + word.length
      processToken(word).foreach { processed =>
        results += ((processed, start, end))
      }
      currentPos = end
    }

    results.toList
  }

  def countTokens(text: String): Int = tokenize(text).length
}

// ============================================================================
// Builder Pattern with Fluent Interface
// ============================================================================

final class TokenizerBuilder[T] {
  private val normalizers = ListBuffer.empty[String => String]
  private val validators = ListBuffer.empty[T => Boolean]
  private val metadata = mutable.Map.empty[String, Any]

  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] = {
    normalizers += normalizer
    this
  }

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] = {
    validators += validator
    this
  }

  def withMetadata(entries: (String, Any)*): TokenizerBuilder[T] = {
    metadata ++= entries
    this
  }

  def build(): T => Token = {
    val normalizerSnapshot = normalizers.toList
    val validatorSnapshot = validators.toList
    val metadataSnapshot = metadata.toMap

    (value: T) => {
      validatorSnapshot.foreach { validator =>
        if (!validator(value)) throw new IllegalArgumentException(s"Validation failed for $value")
      }

      var strValue = value.toString
      normalizerSnapshot.foreach { normalizer =>
        strValue = normalizer(strValue)
      }

      Token(strValue, TokenType.STRING, metadataSnapshot)
    }
  }
}
